// v4.3.0: shared, allowlisted presentation palettes. Settings remain server-authoritative.
window.AtlasTheme=(()=>{
 const palettes=[{"id": "coastal", "name": "Coastal Teal", "description": "Familiar teal with cool blue-grey surfaces.", "accent": "#175b67", "text": "#17313e", "muted": "#4e6570", "page": "#f9fbfc", "soft": "#eff5f8", "highlight": "#e3f1f7", "edge": "#427b93", "border": "#ccdbe2"}, {"id": "ocean", "name": "Ocean Blue", "description": "Clear navy and blue for crisp navigation.", "accent": "#205493", "text": "#182c45", "muted": "#4c6178", "page": "#f8faff", "soft": "#edf2fa", "highlight": "#deebfc", "edge": "#3e6fa5", "border": "#cbd7e8"}, {"id": "forest", "name": "Forest", "description": "Deep green with quiet sage surfaces.", "accent": "#286047", "text": "#20362b", "muted": "#506658", "page": "#f8fbf8", "soft": "#eef5ee", "highlight": "#e0efdf", "edge": "#4b785b", "border": "#cbdccb"}, {"id": "plum", "name": "Plum", "description": "Muted purple with soft lavender surfaces.", "accent": "#6c427d", "text": "#35273d", "muted": "#69566f", "page": "#fcf9fd", "soft": "#f4eef7", "highlight": "#eee0f5", "edge": "#866194", "border": "#ddcfe3"}, {"id": "slate", "name": "Slate", "description": "Neutral charcoal with minimal colour distraction.", "accent": "#3c5365", "text": "#222f39", "muted": "#53626d", "page": "#fafbfc", "soft": "#f0f3f5", "highlight": "#e3eaf0", "edge": "#637889", "border": "#d1dbe2"}];
 function apply(id){const palette=palettes.find(p=>p.id===id)||palettes[0];document.documentElement.dataset.palette=palette.id;return palette;}
 return {palettes,apply};
})();
fetch('/api/config',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(config=>{if(config&&!document.documentElement.dataset.palettePreview)AtlasTheme.apply(config.palette);}).catch(()=>{});
